  const clave = mes.toISOString().slice(0, 7);
  const delMes = ops.filter((o) => String(o.fecha_cierre || o.fecha_venta).startsWith(clave));

  if (!delMes.length) return { resumen: 'Sin operaciones registradas en ' + clave + '.' };

  const capital = num(inputs.capital);
  let primaBruta = 0, recompras = 0, cerradas = 0, asignadas = 0, tomas5070 = 0;
  for (const o of delMes) {
    const mult = (num(o.contratos) || 1) * 100;
    primaBruta += num(o.prima_cobrada) * mult;
    if (o.fecha_cierre) {
      cerradas++;
      recompras += num(o.costo_recompra) * mult;
      if (String(o.asignado).toLowerCase() === 'si') asignadas++;
      const cap = num(o.prima_cobrada) > 0 ? 1 - num(o.costo_recompra) / num(o.prima_cobrada) : 0;
      if (cap >= 0.5 && cap <= 0.75) tomas5070++;
    }
  }
  const neta = primaBruta - recompras;
  const tasaAsig = cerradas ? asignadas / cerradas : 0;
  const lineas = [
    'Informe del mes ' + clave + ' (' + delMes.length + ' operaciones, ' + cerradas + ' cerradas):',
    'Prima bruta cobrada: $' + primaBruta.toFixed(2),
    'Recompras: $' + recompras.toFixed(2),
    'Prima neta: $' + neta.toFixed(2) + (capital > 0 ? ' (' + ((neta / capital) * 100).toFixed(2) + '% sobre capital de $' + capital + ')' : ''),
    'Tasa de asignacion: ' + (tasaAsig * 100).toFixed(0) + '%',
    'Cierres en la banda 50-70%: ' + tomas5070 + ' de ' + cerradas,
  ];
  // Regla del registro: asignacion sostenida > 30% => deltas demasiado altos
  if (tasaAsig > 0.3) lineas.push('AVISO: tasa de asignacion > 30% — estas vendiendo deltas demasiado altos.');
  return { resumen: lineas.join('\n') };
};
